<section class="auth-section container-wide"><div class="auth-story"><span class="eyebrow">YOUR NEXT FAVOURITE IS WAITING</span><h1>A familiar flavour.<br>A fresh beginning.</h1><img src="<?= e(asset(setting('hero_image','assets/images/hero.png'))) ?>" alt="Prakshi pickle jars"><p>A little jar. A whole lot of home.</p></div><div class="auth-panel"><span class="eyebrow">WELCOME TO PRAKSHI</span><h2><?= ['login'=>'Good to have you back.','register'=>'Join our table.','forgot'=>'Forgot your password?','reset'=>'A fresh start.'][$mode] ?></h2><p><?= $mode==='forgot'?'Enter your email and we’ll send a reset link.':'Your favourite flavours are just a step away.' ?></p><form method="post" action="<?= e(url($mode)) ?>"><?= csrf() ?><?php if($mode==='register'): ?><label>Full name<input class="form-control" name="name" required autocomplete="name"></label><label>Mobile number (optional)<input class="form-control" name="mobile" type="tel" autocomplete="tel"></label><?php endif ?><?php if($mode!=='reset'): ?><label>Email address<input class="form-control" name="email" type="email" required autocomplete="email"></label><?php else: ?><input type="hidden" name="token" value="<?= e($_GET['token']??'') ?>"><?php endif ?><?php if($mode!=='forgot'): ?><label>Password<input class="form-control" type="password" name="password" required <?= $mode!=='login'?'minlength="10"':'' ?> autocomplete="<?= $mode==='login'?'current-password':'new-password' ?>"></label><?php endif ?><?php if(in_array($mode,['register','reset'])): ?><label>Confirm password<input class="form-control" type="password" name="password_confirmation" required minlength="10" autocomplete="new-password"></label><?php endif ?><?php if($mode==='register'): ?><label class="consent"><input type="checkbox" name="consent" required> I agree to the <a href="<?= e(url('page',['slug'=>'terms'])) ?>">terms</a> and <a href="<?= e(url('page',['slug'=>'privacy'])) ?>">privacy policy</a>.</label><?php endif ?><button class="btn btn-primary w-100"><?= ['login'=>'Log in →','register'=>'Create account →','forgot'=>'Send reset link →','reset'=>'Update password →'][$mode] ?></button></form><div class="auth-links"><?php if($mode==='login'): ?><a href="<?= e(url('forgot')) ?>">Forgot password?</a><p>New to our table? <a href="<?= e(url('register')) ?>">Create an account</a></p><?php else: ?><a href="<?= e(url('login')) ?>">Back to log in</a><?php endif ?></div></div></section>
